/* Original fictional management economy. Not a model of the datathon data. */
(function(root){'use strict';
const zones=['Neon entrance','Velvet lounge','Back Forty'],menus=[{name:'Value',price:5,demand:1.2,mood:5},{name:'Classic',price:9,demand:1,mood:2},{name:'Fancy',price:14,demand:.8,mood:-5}],staff=[{name:'Small crew',cost:70,wear:12,mood:-4},{name:'Full crew',cost:180,wear:7,mood:3},{name:'VIP service',cost:310,wear:3,mood:7}],events=[{name:'Opening night',icon:'✦',text:'Everyone wants a look. Make a good first impression.',demand:1.15,zone:0},{name:'Convention crowd',icon:'♣',text:'Visitors are arriving in groups. Expect a busy entrance.',demand:1.5,zone:0},{name:'Quiet Tuesday',icon:'☾',text:'A slower night. A good time to keep costs sensible.',demand:.75,zone:1},{name:'Jazz in the lounge',icon:'♫',text:'The lounge is the place to be tonight.',demand:1.3,zone:1},{name:'Rain on the Strip',icon:'☂',text:'Guests who came inside are settling in for the evening.',demand:1.1,zone:2},{name:'Weekend rush',icon:'★',text:'The whole floor is buzzing. Bring enough staff.',demand:1.65,zone:0},{name:'Local regulars',icon:'♥',text:'Familiar faces appreciate good value and a friendly crew.',demand:1,zone:2}];
const clone=s=>JSON.parse(JSON.stringify(s)),clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
function fresh(seed=2026){return {v:1,seed:seed>>>0,day:1,cash:2400,rating:62,prestige:0,totalGuests:0,profitDays:0,earned:0,menu:1,crew:1,promo:0,nextId:4,machines:[{id:1,z:0,l:1,wear:8},{id:2,z:0,l:1,wear:15},{id:3,z:1,l:1,wear:22}],claimed:[],last:null,history:[]};}
function valid(s){return !!s&&s.v===1&&Number.isInteger(s.seed)&&s.seed>=0&&s.seed<=4294967295&&Number.isSafeInteger(s.nextId)&&s.nextId>Math.max(...(Array.isArray(s.machines)?s.machines.map(m=>m?.id||0):[0]))&&Number.isSafeInteger(s.day)&&s.day>=1&&Number.isFinite(s.cash)&&s.cash>=0&&Number.isFinite(s.rating)&&s.rating>=0&&s.rating<=100&&Number.isInteger(s.prestige)&&s.prestige>=0&&[s.totalGuests,s.profitDays,s.earned].every(Number.isFinite)&&[0,1,2].includes(s.menu)&&[0,1,2].includes(s.crew)&&[0,1,2].includes(s.promo)&&Array.isArray(s.claimed)&&Array.isArray(s.history)&&Array.isArray(s.machines)&&s.machines.length>0&&s.machines.length<=12&&new Set(s.machines.map(m=>m?.id)).size===s.machines.length&&s.machines.every(m=>m&&Number.isSafeInteger(m.id)&&m.id>0&&[0,1,2].includes(m.z)&&[1,2,3].includes(m.l)&&Number.isFinite(m.wear)&&m.wear>=0&&m.wear<=100)&&zones.every((_,z)=>s.machines.filter(m=>m.z===z).length<=4);}
function forecast(s){return events[(s.day-1)%events.length];}
function cost(s,type,id){const m=s.machines.find(x=>x.id===id);return type==='buy'?700+s.machines.length*150:type==='repair'&&m?80+m.l*40:type==='upgrade'&&m?m.l*650:type==='move'?80:0;}
function action(state,type,id,z){const s=clone(state),m=s.machines.find(x=>x.id===id),price=cost(s,type,id);if(!['buy','repair','upgrade','move'].includes(type))throw Error('Unknown action');if(s.cash<price)throw Error('Save a little more cash first.');if(type==='buy'){if(![0,1,2].includes(z)||s.machines.filter(m=>m.z===z).length>=4)throw Error('That area is full.');s.machines.push({id:s.nextId++,z,l:1,wear:0});}else{if(!m)throw Error('Choose a machine first.');if(type==='repair'){if(m.wear===0)throw Error('This machine is already in great shape.');m.wear=0;}if(type==='upgrade'){if(m.l>=3)throw Error('Already fully upgraded.');m.l++;m.wear=Math.max(0,m.wear-15);}if(type==='move'){if(![0,1,2].includes(z)||z===m.z||s.machines.filter(m=>m.z===z).length>=4)throw Error('Choose a different area with an empty space.');m.z=z;}}s.cash-=price;return s;}
function goals(s){return [{id:'guests',title:'Welcome 40 guests',value:s.totalGuests,target:40,reward:400},{id:'machines',title:'Build a five-machine floor',value:s.machines.length,target:5,reward:650},{id:'profit',title:'Run five profitable nights',value:s.profitDays,target:5,reward:900},{id:'rating',title:'Reach 85 guest happiness',value:s.rating,target:85,reward:1200},{id:'empire',title:'Fill all 12 spaces',value:s.machines.length,target:12,reward:2000}];}
function shift(state,response='host'){if(!['host','tech','drinks'].includes(response))throw Error('Unknown response');if(!valid(state))throw Error('Invalid save');const s=clone(state);let seed=s.seed;const rand=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;};const event=forecast(s),menu=menus[s.menu],crew=staff[s.crew],marketing=[0,120,280][s.promo];const visitors=Math.round((60+Math.min(s.day,120)*1.4+s.prestige*12)*event.demand*menu.demand*(.7+s.rating/150)*(1+s.promo*.22)*(.9+rand()*.2));let served=0,revenue=0,broken=0;let assigned=0;const shares=[.43,.34,.23];shares[event.zone]+=.18;const sum=shares.reduce((a,b)=>a+b,0),zoneResults=[];
for(let z=0;z<3;z++){const machines=s.machines.filter(m=>m.z===z),demand=z===2?visitors-assigned:Math.round(visitors*shares[z]/sum);assigned+=demand;let capacity=0;for(const m of machines){const jam=m.wear>=95||(m.wear>55&&rand()<m.wear/350);if(jam){broken++;m.wear=100;}else capacity+=Math.round((15+m.l*7)*(1-m.wear/140));m.wear=clamp(m.wear+crew.wear+(rand()*4),0,100);}if(response==='tech'&&capacity>0)capacity+=10;const visits=Math.min(demand,capacity),gross=Math.round(visits*(11+menu.price*.65)*(1+s.prestige*.06));served+=visits;revenue+=gross;zoneResults.push({z,demand,served:visits,capacity,revenue:gross});}
const operating=crew.cost+marketing+100+s.machines.length*24+Math.min(250,s.day*4),responseCost=response==='drinks'?75:0;const net=revenue-operating-responseCost;const missed=visitors-served;const mood=crew.mood+menu.mood+(response==='host'?4:response==='drinks'?7:0)-Math.round(missed/Math.max(1,visitors)*12)-broken*2;s.rating=clamp(s.rating+mood,15,100);const before=s.cash;s.cash=Math.max(0,s.cash+net);s.earned+=net;s.totalGuests+=served;if(net>0)s.profitDays++;const rewards=[];for(const goal of goals(s)){if(!s.claimed.includes(goal.id)&&goal.value>=goal.target){s.claimed.push(goal.id);s.cash+=goal.reward;rewards.push(goal);}}s.last={day:s.day,event:event.name,visitors,served,missed,broken,revenue,operating,responseCost,net,rewards,cashChange:s.cash-before,response,zoneResults,rating:s.rating};s.history=[...s.history,{day:s.day,net,rating:s.rating}].slice(-30);s.day++;s.seed=seed;return s;}
function nextResort(state){if(state.cash<20000)throw Error('Save $20,000 to open the next resort.');const s=fresh(state.seed);s.prestige=state.prestige+1;s.cash=2400+s.prestige*400;s.rating=65;return s;}
function rescue(state){if(state.cash>=300)throw Error('Your casino still has working cash.');const s=clone(state);s.cash=1200;s.machines=[{id:s.nextId++,z:0,l:1,wear:0}];s.rating=55;s.menu=0;s.crew=0;s.promo=0;s.last=null;return s;}
function compare(s){return ['host','tech','drinks'].map(response=>{const x=shift(s,response).last;return {response,net:x.net,guests:x.served,happiness:x.rating};});}
const api={fresh,valid,forecast,cost,action,shift,goals,nextResort,rescue,compare,zones,menus,staff};root.AceSimCore=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window==='undefined'?globalThis:window);
